from pathlib import Path
p=Path('apps/storefront/components/store.tsx');s=p.read_text(encoding='utf-8');old='<div className="announcement"><div className="container"><span>Thoughtfully chosen. Delivered to your door.</span><span><Truck size={13}/>Delivery across selected Kenyan counties</span></div></div>';new='<div className="announcement announcement-marquee" aria-label="Thoughtfully chosen. Delivered to your door. Delivery across selected Kenyan counties."><div className="announcement-track">{[0,1].map(copy=><div className="announcement-group" key={copy} aria-hidden={copy===1?true:undefined}>{[0,1].map(item=><React.Fragment key={item}><span>Thoughtfully chosen. Delivered to your door.</span><span className="announcement-divider" aria-hidden="true">✦</span><span><Truck size={13}/>Delivery across selected Kenyan counties</span><span className="announcement-divider" aria-hidden="true">✦</span></React.Fragment>)}</div>)}</div></div>';assert old in s;s=s.replace(old,new).replace('<React.Fragment key={item}>','<span className="announcement-pair" key={item}>').replace('</React.Fragment>','</span>');p.write_text(s,encoding='utf-8')
